=== footer/index.tsx getEntries call (lines 175-200) ===
  const { client } = useContentfulClient();
  const [footerData, setFooterData] = useState<FooterConfigEntry | null>(null);

  useEffect(() => {
    if (!client) return;
    let cancelled = false;

    client
      .getEntries({ content_type: 'footerConfig', include: 3 })
      .then((response) => {
        if (cancelled) return;
        // The contentful SDK client is loosely typed (see useContentfulClient.ts) —
        // FooterConfigEntry mirrors the exact nested-resolved shape `include: 3` produces
        // for this content model.
        const configs = response.items as unknown as FooterConfigEntry[];
        const resolved = pickMostSpecificByRegion<FooterConfigEntry>(configs, site.id);
        setFooterData(resolved ? scopeToRegion(resolved, site.id) : null);
      })
      .catch(() => {
        if (!cancelled) setFooterData(null);
      });

    return () => {
      cancelled = true;
    };
  }, [client, site.id]);

